document.addEventListener("DOMContentLoaded",()=>{const loader=document.getElementById("loading-screen");const content=document.getElementById("content");const percentageText=document.getElementById("percentage");if(loader && content && percentageText){if(window.location.hash || sessionStorage.getItem("homeLoaded")){loader.style.display="none";}else{sessionStorage.setItem("homeLoaded","true");let count=0;const interval=setInterval(()=>{if(count <=100){percentageText.textContent=`[${count}%]`;count++;}else{clearInterval(interval);loader.style.display="none";window.__loaderDone=true;}},10);}}});